def transform(grid):
    g=[r[:] for r in grid]
    # identify enclosing hollow rectangle and fill its interior with color 2
    from collections import Counter
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    colors=set(x for row in g for x in row)-{bg}
    for c in colors:
        pts=[(r,k) for r,row in enumerate(g) for k,x in enumerate(row) if x==c]
        r0=min(r for r,k in pts); r1=max(r for r,k in pts); c0=min(k for r,k in pts); c1=max(k for r,k in pts)
        if len(pts)==2*(r1-r0+c1-c0):
            for r in range(r0+1,r1):
                for k in range(c0+1,c1):
                    if g[r][k]==bg:g[r][k]=2
            return g
        # small 3x3 ring with center background: set center 7
        if r1-r0==2 and c1-c0==2 and len(pts)==8:
            g[(r0+r1)//2][(c0+c1)//2]=7
    return g
